using System;
using System.IO;
using WoWProbe;
class QuickRouteTests
{
    static int passed,failed;static void Check(bool b){if(!b)throw new Exception("Fixed route behavior differs.");}
    static QuickRoutePlan Plan()
    {
        var r=new RouteDocument{RouteId="manual",Name="ABCDA",MapId=1432,MapMode=1,Zone="TEST",Loop=true};
        foreach(var p in new[]{new[]{.5,.5},new[]{.56,.5},new[]{.56,.56},new[]{.5,.56},new[]{.5,.5}})r.Points.Add(new Waypoint{X=p[0],Y=p[1],Tolerance=.001});
        return new QuickRoutePlan{Route=r,Calibration=new NavigationCalibration{MapId=1432,MapMode=1,Zone="TEST",AxisScale=1.5,TurnRadiansPerSecond=5.85,Confirmed=true}};
    }
    static FarmObservation O(){return new FarmObservation{Fresh=true,KnownCore=true,MapId=1432,MapMode=1,Zone="TEST",X=.5,Y=.5,Facing=3*Math.PI/2,Health=100,PowerType=3,FoodCount=10,CastingKnown=true,ChatOpenKnown=true};}
    static QuickCommand Step(QuickRouteFollower f,FarmObservation o,long time){o.Sequence++;return f.Step(o,time);}
    static QuickCommand Step(QuickCombat f,FarmObservation o,long time){o.Sequence++;return f.Step(o,time);}
    static void Reject(Action a){bool rejected=false;try{a();}catch(ArgumentException){rejected=true;}catch(FormatException){rejected=true;}catch(InvalidOperationException){rejected=true;}Check(rejected);}
    static void Test(string s,Action a){try{a();passed++;Console.WriteLine("PASS "+s);}catch(Exception e){failed++;Console.WriteLine("FAIL "+s+": "+e.Message);}}
    static void Target(FarmObservation o){o.TargetExists=o.TargetIdentityKnown=o.AttackabilityKnown=o.TargetCanAttack=o.TargetDeadKnown=true;o.TargetToken=8;o.TargetReaction=4;}
    static int Main()
    {
        Test("multiple failed targets stay skipped while patrol advances but attackers override cooldown",()=>{var o=O();Target(o);var f=new QuickRouteFollower(Plan(),o);f.TickNearbySearch(o,0,true);f.TickNearbySearch(o,2600,true);Step(f,o,2600);var e=new QuickCombat(o,750,false,f);Step(e,o,2700);Check(Step(e,o,14700).Action==QuickAction.ReturnToRoute);Step(e,o,14800);o.TargetToken=9;Step(e,o,14900);Check(Step(e,o,26900).Action==QuickAction.ReturnToRoute);o.TargetToken=8;var c=Step(e,o,27000);Check(c.RouteMovement&&QuickCombat.Matches(c,o)&&!e.ShouldAcquire(o,27000));o.TargetToken=9;Check(QuickCombat.Matches(c,o)&&!e.ShouldAcquire(o,27100));o.TargetToken=10;Check(!QuickCombat.Matches(c,o)&&e.ShouldAcquire(o,27200));o.TargetToken=8;o.InCombat=true;Check(e.ShouldAcquire(o,27300)&&!QuickCombat.Matches(c,o));o.InCombat=false;Check(e.ShouldAcquire(o,44700));o.TargetToken=9;Check(!e.ShouldAcquire(o,44700)&&e.ShouldAcquire(o,56900));});
        Test("crossing pursuit boundary abandons target and rejoins without stopping",()=>{var o=O();Target(o);var f=new QuickRouteFollower(Plan(),o);var e=new QuickCombat(o,750,false,f);Step(e,o,0);o.X=.53;o.Y=.525;Check(!f.CanOperate(o));var c=Step(e,o,100);Check(c.Action==QuickAction.ReturnToRoute&&f.Joining&&f.Returning&&!f.SearchingNearby&&QuickCombat.Matches(c,o)&&e.Kills==0);o.TargetToken++;Check(!e.ShouldAcquire(o,200));c=Step(e,o,200);Check(c.RouteMovement&&QuickCombat.Matches(c,o));o.X=o.Y=.5;Step(e,o,300);Check(!f.Joining&&!f.Returning&&e.ShouldAcquire(o,400));Check(Step(e,o,400).Action!=QuickAction.Stop);});
        Test("rejoin rejects unreadable changed-map dead ghost and combat observations",()=>{for(int i=0;i<10;i++){var o=O();var f=new QuickRouteFollower(Plan(),o);switch(i){case 0:o.Fresh=false;break;case 1:o.KnownCore=false;break;case 2:o.ReadFailures=1;break;case 3:o.MapId++;break;case 4:o.X=Double.NaN;break;case 5:o.Y=1.1;break;case 6:o.PlayerDead=true;break;case 7:o.PlayerGhost=true;break;case 8:o.InCombat=true;break;case 9:o.Facing=Double.NaN;break;}Check(!f.TryRejoin(o)&&!f.Joining);}});
        Test("moving pursuit continues past twelve seconds while a bounded failed attempt returns to patrol",()=>{var o=O();Target(o);var f=new QuickRouteFollower(Plan(),o);var e=new QuickCombat(o,750,false,f);Step(e,o,0);for(int t=500;t<=30000;t+=500){o.X+=.0001;var c=Step(e,o,t);Check(c.Action!=QuickAction.ReturnToRoute&&c.Action!=QuickAction.Stop);}var end=Step(e,o,45000);Check(end.Action==QuickAction.ReturnToRoute&&QuickCombat.Matches(end,o));});
        Test("ranged combat option is saved cloned and defaults to melee",()=>{var p=Plan();Check(!p.RangedCombat);p.RangedCombat=true;Check(p.Clone().RangedCombat);var file=Path.GetTempFileName();try{QuickRoutePlan.Save(file,p);Check(QuickRoutePlan.Load(file).RangedCombat);var text=File.ReadAllText(file).Replace("\"RangedCombat\":true,","");File.WriteAllText(file,text);Check(!QuickRoutePlan.Load(file).RangedCombat);}finally{File.Delete(file);}});
        Test("hostile option persists and allows only eligible hostile NPCs",()=>{var p=Plan();Check(!p.AttackHostile);p.AttackHostile=true;Check(p.Clone().AttackHostile);string path=Path.GetTempFileName();try{QuickRoutePlan.Save(path,p);Check(QuickRoutePlan.Load(path).AttackHostile);}finally{File.Delete(path);}foreach(bool enabled in new[]{false,true})foreach(int reaction in new[]{1,2,3,4,5,255}){p=Plan();p.AttackHostile=enabled;var o=O();Target(o);o.TargetReaction=reaction;var e=new QuickCombat(o,750,false,new QuickRouteFollower(p,o));Check(e.ShouldAcquire(o,0)==(reaction==4||enabled&&reaction>=1&&reaction<=3));o.TargetClaimKnown=o.TargetClaimedByOther=true;Check(!e.ShouldAcquire(o,0));o.TargetClaimedByOther=false;o.TargetIsPlayer=true;Check(!e.ShouldAcquire(o,0));}});
        Test("no chat hotkeys and interaction skin round trip with saved route",()=>{var p=Plan();p.NoChatCombat=true;p.SkinWithInteract=true;p.StartAttackKey="1";p.LastTargetKey="F8";p.StopAttackKey="F9";string file=Path.Combine(Path.GetTempPath(),"wow-hotkeys-"+Guid.NewGuid()+".json");try{QuickRoutePlan.Save(file,p);var q=QuickRoutePlan.Load(file);Check(q.NoChatCombat&&q.SkinWithInteract&&q.Clone().SkinWithInteract&&q.StartAttackKey=="1"&&q.LastTargetKey=="F8"&&q.StopAttackKey=="F9");Check(QuickCombatHotkeys.ActionKey(QuickAction.Skin,q)==70&&QuickCombatHotkeys.ActionKey(QuickAction.Loot,q)==70&&QuickCombatHotkeys.ActionKey(QuickAction.CorpseSelect,q)==119);File.WriteAllText(file,File.ReadAllText(file).Replace("\"SkinWithInteract\":true,",""));q=QuickRoutePlan.Load(file);Check(!q.SkinWithInteract&&QuickCombatHotkeys.ActionKey(QuickAction.Skin,q)==55);}finally{if(File.Exists(file))File.Delete(file);}});
        Test("ABCDA advances in order and loops beyond the legacy four-coordinate radius",()=>{var p=Plan();var o=O();var f=new QuickRouteFollower(p,o);Step(f,o,0);long t=100;for(int lap=0;lap<3;lap++)for(int i=1;i<5;i++){o.X=p.Route.Points[i].X;o.Y=p.Route.Points[i].Y;Check(Step(f,o,t).Action!=QuickAction.Stop);t+=100;Check(f.TargetIndex==(i==4?1:i+1));}Check(f.Laps==3);});
        Test("corridor follows segments instead of accepting the polygon interior",()=>{var p=Plan();Check(p.Contains(.53,.5));Check(!p.Contains(.53,.53));Check(!p.Contains(Double.NaN,.5));Check(!p.Contains(.53,.51));});
        Test("loop closure invalid numbers wrong purpose and mismatched calibration are rejected",()=>{for(int i=0;i<5;i++){var p=Plan();if(i==0)p.Route.Points[4].X=.51;if(i==1)p.Route.Points[1].X=Double.NaN;if(i==2)p.Route.RouteType="vendor_return";if(i==3)p.Calibration.MapId++;if(i==4)p.Calibration.Confirmed=false;Reject(()=>p.Validate(true));}});
        Test("input snapshots are isolated from subsequent edits",()=>{var p=Plan();var o=O();var f=new QuickRouteFollower(p,o);p.Route.Points[1].X=.9;p.CorridorWidth=.02;Check(f.Plan.Route.Points[1].X==.56&&f.Plan.CorridorWidth==.005);});
        Test("map change and route departure stop without joining an arbitrary remote segment",()=>{var o=O();var f=new QuickRouteFollower(Plan(),o);o.X=.53;o.Y=.53;Check(Step(f,o,0).Action==QuickAction.Stop);o=O();f=new QuickRouteFollower(Plan(),o);o.MapId++;Check(Step(f,o,0).Action==QuickAction.Stop);Reject(()=>new QuickRouteFollower(Plan(),o));});
        Test("combat interruption returns to the original leg before advancing",()=>{var o=O();o.X=.53;var f=new QuickRouteFollower(Plan(),o);Step(f,o,0);f.Interrupt(o);o.Y=.502;f.Resume();Check(f.Returning&&f.TargetIndex==1);Step(f,o,100);Check(f.Returning&&f.TargetIndex==1);o.Y=.5;Step(f,o,200);Check(!f.Returning&&f.TargetIndex==1);});
        Test("unknown-position nearby neutral is locked and approached instead of waiting on the line",()=>{var o=O();Target(o);var f=new QuickRouteFollower(Plan(),o);var e=new QuickCombat(o,750,false,f);Check(Step(e,o,0).Action==QuickAction.None);var c=Step(e,o,200);Check(c.Action==QuickAction.Face&&QuickCombat.Matches(c,o));o.X=o.Y=.51;Check(!f.OnRoute(o)&&f.CanOperate(o)&&QuickCombat.Matches(c,o));o.RangeKnown=o.TargetInRange=true;o.InCombat=true;Check(Step(e,o,600).Action==QuickAction.Skill);});
        Test("known off-route targets never authorize proactive facing or skill attacks",()=>{var o=O();Target(o);o.TargetPositionKnown=true;o.TargetX=.53;o.TargetY=.53;var e=new QuickCombat(o,750,false,new QuickRouteFollower(Plan(),o));Check(Step(e,o,0).Action==QuickAction.Scan);Check(Step(e,o,200).Action!=QuickAction.Face);});
        Test("route motion authorization is revoked at the boundary or on combat",()=>{var o=O();var f=new QuickRouteFollower(Plan(),o);var c=Step(f,o,0);Check(QuickCombat.Matches(c,o));o.InCombat=true;Check(!QuickCombat.Matches(c,o));o.InCombat=false;o.X=.53;o.Y=.53;Check(!QuickCombat.Matches(c,o));});
        Test("confirmed kill and loot search nearby before resuming a waypoint",()=>{var o=O();Target(o);o.TargetPositionKnown=true;o.TargetX=.501;o.TargetY=.5;var f=new QuickRouteFollower(Plan(),o);var e=new QuickCombat(o,750,false,f);Step(e,o,0);Step(e,o,100);o.TargetDead=true;o.TargetCanAttack=false;Step(e,o,200);Step(e,o,300);Check(Step(e,o,800).Action==QuickAction.Loot);o.LootEventsKnown=true;o.LootOpened=o.LootClosed=1;Step(e,o,1500);o.TargetExists=false;o.Y=.502;var c=Step(e,o,1600);Check(e.Kills==1&&e.Loots==1&&f.SearchingNearby&&f.TargetIndex==1&&c.Action==QuickAction.Scan);});
        Test("death outside the farm corridor can initialize separate configured recovery without enabling patrol",()=>{var o=O();o.PlayerGhost=true;o.X=.32;o.Y=.47;var f=new QuickRouteFollower(Plan(),o);Check(!f.OnRoute(o)&&f.Returning);});
        Test("saved plans round-trip points and clear machine calibration confirmation",()=>{var p=Plan();string file=Path.Combine(Path.GetTempPath(),"wow-route-"+Guid.NewGuid()+".json");try{QuickRoutePlan.Save(file,p);var q=QuickRoutePlan.Load(file);Check(q.Route.Fingerprint()==p.Route.Fingerprint()&&!q.Calibration.Confirmed);Reject(()=>q.Validate(true));}finally{if(File.Exists(file))File.Delete(file);}});
        Test("stationary path starts recovery and duplicate frames never silently advance",()=>{var o=O();var f=new QuickRouteFollower(Plan(),o);Step(f,o,0);Check(f.Step(o,100).Action==QuickAction.None&&f.TargetIndex==1);Check(Step(f,o,2600).Action==QuickAction.BackOff);Check(Step(f,o,2900).Action==QuickAction.DetourTurn);Check(Step(f,o,3100).Action==QuickAction.None);Check(Step(f,o,6000).Action==QuickAction.Stop);});
        Test("known nearby mob may be off the patrol line but inside the pursuit area",()=>{var o=O();Target(o);o.TargetPositionKnown=true;o.TargetX=.53;o.TargetY=.51;var f=new QuickRouteFollower(Plan(),o);Check(!f.Plan.Contains(o.TargetX,o.TargetY)&&f.MayAcquire(o));var e=new QuickCombat(o,750,false,f);Step(e,o,0);Check(Step(e,o,100).Action==QuickAction.Face);});
        Test("off-line kill and loot allow the next nearby mob before returning",()=>{var o=O();o.X=.53;Target(o);var f=new QuickRouteFollower(Plan(),o);var e=new QuickCombat(o,750,false,f);Step(e,o,0);o.Y=.51;o.InCombat=true;Step(e,o,100);o.TargetDead=true;o.TargetCanAttack=false;o.InCombat=false;Step(e,o,200);Step(e,o,300);Check(Step(e,o,800).Action==QuickAction.Loot);o.LootEventsKnown=true;o.LootOpened=o.LootClosed=1;Step(e,o,1500);o.TargetToken=9;o.TargetDead=false;o.TargetCanAttack=true;Step(e,o,1600);Check(e.Kills==1&&e.Loots==1&&f.SearchingNearby);Check(Step(e,o,1700).Action==QuickAction.Face);});
        Test("unreachable target times out into return and is not immediately reacquired",()=>{var o=O();Target(o);var f=new QuickRouteFollower(Plan(),o);var e=new QuickCombat(o,750,false,f);Step(e,o,0);var c=Step(e,o,12000);Check(c.Action==QuickAction.ReturnToRoute&&QuickCombat.Matches(c,o)&&e.Kills==0);c=Step(e,o,12100);Check(c.RouteMovement&&QuickCombat.Matches(c,o)&&!e.ShouldAcquire(o,12100));o.TargetToken++;Check(e.ShouldAcquire(o,12200)&&!QuickCombat.Matches(c,o));});
        Test("approach at pursuit boundary returns but combat interrupts return to defend",()=>{var o=O();Target(o);var f=new QuickRouteFollower(Plan(),o);var e=new QuickCombat(o,750,false,f);Step(e,o,0);o.X=.53;o.Y=.5195;Check(Step(e,o,100).Action==QuickAction.ReturnToRoute);o.InCombat=true;o.TargetReaction=2;Step(e,o,200);Check(Step(e,o,300).Action==QuickAction.Face);});
        Test("attacks during food or return interrupt movement and food even with full bags",()=>{for(int i=0;i<2;i++){var o=O();var f=new QuickRouteFollower(Plan(),o);var e=new QuickCombat(o,750,false,f);if(i==0){o.Health=60;Check(Step(e,o,0).Action==QuickAction.Food);}else{f.Interrupt(o);o.Y=.51;f.Resume();}o.InCombat=true;o.BagFull=true;Target(o);o.TargetReaction=2;Step(e,o,100);Check(Step(e,o,200).Action==QuickAction.Face);o.TargetDead=true;o.TargetCanAttack=false;Step(e,o,300);Step(e,o,400);Check(e.Kills==1);}});
        Test("empty route segments keep scanning and advancing for many patrol laps",()=>{var o=O();var p=Plan();var f=new QuickRouteFollower(p,o);f.TickNearbySearch(o,0,true);f.TickNearbySearch(o,2600,true);Step(f,o,2600);var e=new QuickCombat(o,750,false,f);int motion=0;for(int i=0;i<300;i++){var endpoint=p.Route.Points[f.TargetIndex];o.X+=(endpoint.X-o.X)*.3;o.Y+=(endpoint.Y-o.Y)*.3;var c=Step(e,o,2700+i*250);Check(c.Action!=QuickAction.Stop);if(c.RouteMovement)motion++;}Check(motion>200&&f.Laps>2);});
        Test("self defense finishes then nearby search can expire into a route back",()=>{var o=O();var f=new QuickRouteFollower(Plan(),o);f.Interrupt(o);o.Y=.53;o.InCombat=true;Target(o);o.TargetReaction=2;var e=new QuickCombat(O(),750,false,f);Step(e,o,0);Check(Step(e,o,100).Action==QuickAction.Face);o.TargetDead=true;o.TargetCanAttack=false;o.InCombat=false;Step(e,o,200);Step(e,o,300);o.LootEventsKnown=true;o.LootOpened=o.LootClosed=1;Step(e,o,1000);o.TargetExists=false;Step(e,o,1100);var c=Step(e,o,3700);Check(e.Kills==1&&f.Joining&&c.RouteMovement&&QuickCombat.Matches(c,o));});
        Test("off-route startup first permits nearby mobs then joins the nearest waypoint",()=>{var p=Plan();var o=O();o.X=.60;o.Y=.565;var f=new QuickRouteFollower(p,o);Check(f.Joining&&f.Returning&&f.TargetIndex==3&&f.CanOperate(o));Target(o);Check(f.MayAcquire(o));o.TargetExists=false;f.TickNearbySearch(o,0,true);f.TickNearbySearch(o,2600,true);var c=Step(f,o,2600);Check(c.RouteMovement&&QuickCombat.Matches(c,o));o.X=.56;o.Y=.56;Step(f,o,2700);Check(!f.Joining&&!f.Returning&&f.TargetIndex==3);});
        Test("an observed roadside skinnable corpse is approached and skinned without kill credit",()=>{var o=O();Target(o);o.TargetDead=true;o.TargetCanAttack=false;o.SkinKnown=o.Skinnable=o.SkinBindingKnown=o.SkinBindingCorrect=o.SkinSuccessKnown=o.CastEventsKnown=o.LootKnown=true;var f=new QuickRouteFollower(Plan(),o);var e=new QuickCombat(o,750,true,f);Check(Step(e,o,0).Action==QuickAction.None);var c=Step(e,o,500);Check(c.Action==QuickAction.CorpseApproach&&e.Kills==0&&QuickCombat.Matches(c,o));Check(Step(e,o,1600).Action==QuickAction.Skin);o.SkinSuccess=1;Step(e,o,3200);Check(e.Skins==1&&e.Kills==0);});
        Test("manual skill configuration persists with the route",()=>{var p=Plan();p.OpeningKeys="24";p.LoopKeys="242223";p.SkillIntervalMs=1225;string path=Path.Combine(Path.GetTempPath(),"wow-skills-"+Guid.NewGuid()+".json");try{QuickRoutePlan.Save(path,p);var q=QuickRoutePlan.Load(path);Check(q.OpeningKeys=="24"&&q.LoopKeys=="242223"&&q.SkillIntervalMs==1225);q.LoopKeys="";Reject(()=>q.Validate(false));}finally{if(File.Exists(path))File.Delete(path);}});
        Test("far off-route startup can approach a mob beside the current position first",()=>{var o=O();o.X=o.Y=.65;Target(o);var f=new QuickRouteFollower(Plan(),o);var e=new QuickCombat(o,750,false,f);Step(e,o,0);var c=Step(e,o,100);Check(c.Action==QuickAction.Face&&QuickCombat.Matches(c,o)&&f.PursuitDistance(o)==0);});
        Test("pre-skill-config JSON imports with defaults instead of requiring the new optional fields",()=>{string path=Path.Combine(Path.GetTempPath(),"wow-legacy-"+Guid.NewGuid()+".json");try{var js=new System.Web.Script.Serialization.JavaScriptSerializer();var fields=js.Deserialize<System.Collections.Generic.Dictionary<string,object>>(js.Serialize(Plan()));foreach(string k in new[]{"CombatRadius","OpeningKeys","LoopKeys","SkillIntervalMs"})fields.Remove(k);File.WriteAllText(path,js.Serialize(fields));var p=QuickRoutePlan.Load(path);Check(p.OpeningKeys=="242223"&&p.LoopKeys=="2"&&p.SkillIntervalMs==750&&p.Route.Points.Count==5);Check(QuickRoutePlan.Import(path).Route.Points.Count==5);fields.Remove("Calibration");File.WriteAllText(path,js.Serialize(fields));Reject(()=>QuickRoutePlan.Load(path));}finally{if(File.Exists(path))File.Delete(path);}});
        Test("old recorded route JSON imports through either route entry without changing its source",()=>{string path=Path.Combine(Path.GetTempPath(),"wow-old-route-"+Guid.NewGuid()+".json");try{var r=Plan().Route;r.Points.RemoveAt(4);r.Loop=false;RouteStore.Save(path,r);string original=File.ReadAllText(path);var p=QuickRoutePlan.Import(path);Check(p.Route.Points.Count==5&&p.Route.Points[1].X==r.Points[1].X&&p.Route.Loop&&!p.Calibration.Confirmed&&File.ReadAllText(path)==original);r.RouteType="corpse_run";RouteStore.Save(path,r);Reject(()=>QuickRoutePlan.Import(path));}finally{if(File.Exists(path))File.Delete(path);}});
        Test("idle patrol departure joins a nearby waypoint rather than stopping the run",()=>{var o=O();var f=new QuickRouteFollower(Plan(),o);f.TickNearbySearch(o,0,true);f.TickNearbySearch(o,2600,true);Step(f,o,2600);o.X=.5;o.Y=.5;var e=new QuickCombat(o,750,false,f);o.X=.49;o.Y=.49;var c=Step(e,o,2700);Check(c.Action!=QuickAction.Stop&&f.Joining&&QuickCombat.Matches(c,o));});
        Test("sharp near-point correction releases forward motion to avoid orbiting the point",()=>{var o=O();o.X=.53;var f=new QuickRouteFollower(Plan(),o);f.Interrupt(o);o.Y=.502;o.Facing=Math.PI;f.Resume();var c=Step(f,o,0);Check(c.Action==QuickAction.Turn&&c.PauseForward);});
        Test("observed right mouse turns allow bounded forward detours and three failed attempts stop",()=>{var o=O();var f=new QuickRouteFollower(Plan(),o);Step(f,o,0);long t=2600;for(int i=0;i<3;i++){Check(Step(f,o,t).Action==QuickAction.BackOff);var c=Step(f,o,t+300);Check(c.Action==QuickAction.DetourTurn&&c.MouseTurn);o.Facing+=.3;Check(Step(f,o,t+600).Action==QuickAction.DetourForward);t+=3300;}Check(Step(f,o,t).Action==QuickAction.Stop&&f.TargetIndex==1);});
        Console.WriteLine("Fixed route tests: "+passed+" passed, "+failed+" failed. No game or native input.");return failed==0?0:1;
    }
}
